"""Actual emitted startup shell guard, no Docker/compiler/weights/device."""
import ast,os,subprocess,tempfile,unittest
from pathlib import Path
HERE=Path(__file__).resolve().parent
class Controls(unittest.TestCase):
 def test_actual_guard_skips_initialized_failure(self):
  tree=ast.parse((HERE/'run_prefill_gdn_projection_operator_v2.py').read_text());strings=[n.value for n in ast.walk(tree)if isinstance(n,ast.Constant)and isinstance(n.value,str)and n.value.startswith('set -Eeo pipefail; if')];self.assertEqual(len(strings),1);prefix=strings[0].split('; ldd ')[0]
  with tempfile.TemporaryDirectory()as d:
   p=Path(d);setter=p/'setvars.sh';setter.write_text('echo invoked >> "$CALL_LOG"\nreturn 3\n');script=prefix.replace('/opt/intel/oneapi/setvars.sh',str(setter)).replace('/out/setvars.log',str(p/'setvars.log'))+'; echo READY';env=dict(os.environ,SETVARS_COMPLETED='1',CALL_LOG=str(p/'calls'));r=subprocess.run(['bash','-c',script],env=env,capture_output=True,text=True);self.assertEqual(r.returncode,0);self.assertEqual(r.stdout,'READY\n');self.assertFalse((p/'calls').exists());env['SETVARS_COMPLETED']='0';r=subprocess.run(['bash','-c',script],env=env,capture_output=True,text=True);self.assertEqual(r.returncode,3);self.assertTrue((p/'calls').exists())
 def test_exact_only_runtime_changes(self):
  prior=(HERE/'run_prefill_gdn_projection_operator_v1.py').read_text();new=(HERE/'run_prefill_gdn_projection_operator_v2.py').read_text();new=new.replace('"""Runtime-only V2: guarded setvars startup, actual immutable V1 ELF/export."""','"""Root-owned bounded NoDri compile and isolated card0 projection fixture."""').replace("PLAN=source.HERE/'prefill-gdn-projection-runtime-source-plan-v2.json'\nBUILD_PLAN=source.HERE/'prefill-gdn-projection-operator-source-plan-v1.json'","PLAN=source.HERE/'prefill-gdn-projection-operator-source-plan-v1.json'").replace(' require(a.mode=="runtime","V2 is runtime-only; immutable V1 build/export reused")\n','').replace("br['source_plan_sha256']==sha(BUILD_PLAN)","br['source_plan_sha256']==source_sha").replace('set -Eeo pipefail; if [[ ${SETVARS_COMPLETED:-0} != 1 ]]; then source /opt/intel/oneapi/setvars.sh > /out/setvars.log 2>&1; fi; ldd /harness/pf-gdn','set -Eeo pipefail; source /opt/intel/oneapi/setvars.sh > /out/setvars.log 2>&1; ldd /harness/pf-gdn').replace("choices=['runtime']","choices=['build','runtime']");self.assertEqual(new,prior)
if __name__=='__main__':unittest.main()
